func (q *Queries) SettlePayout(ctx context.Context, arg SettlePayoutParams) (int64, error) {
	result, err := q.db.Exec(ctx, settlePayout,
		arg.ProviderTransferID,
		arg.LedgerTransactionID,
		arg.SettledAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startPayoutAttempt = `-- name: StartPayoutAttempt :execrows
UPDATE payouts
SET status = 'sending', attempt_count = attempt_count + 1, provider_attempt_id = $1,
    updated_at = $2
WHERE id = $3 AND status = 'approved'
`

type StartPayoutAttemptParams struct {
	ProviderAttemptID *string
	UpdatedAt         time.Time
	ID                uuid.UUID
}

func (q *Queries) StartPayoutAttempt(ctx context.Context, arg StartPayoutAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, startPayoutAttempt, arg.ProviderAttemptID, arg.UpdatedAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
